        CommonHelper:GetComponentSetUITexture("ActiveBg/icon",item,DataTable[index+1]:GetCollectConfig().portraiticon..'.png',self:GetUIModuleID())
        CommonHelper:HButtonSetCallback("UnActiveBg/BtnDetail", item, function()
            CommonHelper:ShowHelpView(DataTable[index+1]:GetCollectConfig().portraitdetail,DataTable[index+1]:GetCollectConfig().portraitname,nil,true)
        end)
